import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetDifficulty{Difficulty: 3}
HARD = bytes.fromhex("03")

# generated by gophertunnel b8bd735:
# &packet.SetDifficulty{Difficulty: 200}
WIDE = bytes.fromhex("c801")

GOLDENS = [
    pytest.param(v2225.SetDifficultyPacket(difficulty=v2225.Difficulty.HARD), HARD, id="hard"),
    pytest.param(v2225.SetDifficultyPacket(difficulty=200), WIDE, id="wide"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_set_difficulty_is_packet_60(version):
    assert version.PACKETS[60] is version.SetDifficultyPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_difficulty_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_difficulty_decodes_from_its_golden(packet, golden):
    assert v2225.SetDifficultyPacket.from_bytes(golden) == packet
